using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

public class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
        // Existing documents use "Discriminator", so we must explicitly preserve it.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Fix 2: EF Core 9 changed the id format from "EntityType|Key" to just "Key".
        // Existing documents have the old compound format; preserve it for compatibility.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

public class Session
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

public class CosmosQueryService
{
    private readonly CosmosDbContext _db;

    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // Fix 3: EF Core 9 Cosmos provider no longer supports synchronous I/O.
    // ToList() / SaveChanges() now throw. Use async equivalents.
    public async Task<List<Session>> GetSessionsAsync()
    {
        return await _db.Sessions.ToListAsync();
    }

    public async Task AddSessionAsync(Session session)
    {
        _db.Sessions.Add(session);
        await _db.SaveChangesAsync();
    }
}

